"""gitignore-style pattern matching. See task.md."""

from __future__ import annotations


class PatternError(ValueError):
    """Raised for a malformed character class or a dangling escape."""


def _remove_trailing_spaces(line: str) -> str:
    """Remove trailing spaces unless escaped by odd backslashes."""
    i = len(line) - 1
    while i >= 0 and line[i] == ' ':
        # Count preceding backslashes
        num_backslashes = 0
        j = i - 1
        while j >= 0 and line[j] == '\\':
            num_backslashes += 1
            j -= 1
        # If odd number of backslashes, the space is escaped
        if num_backslashes % 2 == 1:
            break
        i -= 1
    return line[:i + 1]


def _parse_pattern_line(line: str) -> tuple[bool, bool, str] | None:
    """Parse a pattern line and return (is_negation, is_dir_only, pattern_text) or None."""
    # Step 1: Remove trailing spaces
    line = _remove_trailing_spaces(line)

    # Step 2: Blank line
    if not line:
        return None

    # Step 3: Comment
    if line.startswith('#'):
        return None

    is_negation = False
    # Step 4: Negation
    if line.startswith('!'):
        is_negation = True
        line = line[1:]

    is_dir_only = False
    # Step 5: Directory-only
    if line.endswith('/'):
        is_dir_only = True
        line = line[:-1]

    # Step 6: Check if nothing is left
    if not line:
        return None

    return (is_negation, is_dir_only, line)


def _parse_char_class(segment: str, pos: int) -> tuple[list[str], int]:
    """Parse a character class starting at pos. Returns (matches, new_pos)."""
    pos += 1  # Skip '['
    negated = False

    if pos < len(segment) and segment[pos] == '!':
        negated = True
        pos += 1

    chars = set()
    # First char after '[' or '[!' can be ']' and it's literal
    if pos < len(segment) and segment[pos] == ']':
        chars.add(']')
        pos += 1

    while pos < len(segment):
        if segment[pos] == ']':
            pos += 1
            break
        elif segment[pos] == '\\' and pos + 1 < len(segment):
            chars.add(segment[pos + 1])
            pos += 2
        elif pos + 2 < len(segment) and segment[pos + 1] == '-' and segment[pos + 2] != ']':
            # Range
            start = ord(segment[pos])
            end = ord(segment[pos + 2])
            if end < start:
                raise PatternError(f"Invalid character range: {segment[pos]}-{segment[pos + 2]}")
            for code in range(start, end + 1):
                chars.add(chr(code))
            pos += 3
        else:
            chars.add(segment[pos])
            pos += 1
    else:
        raise PatternError(f"Unterminated character class in segment: {segment}")

    if negated:
        return ('!', chars), pos
    else:
        return ('', chars), pos


def _compile_segment(segment: str) -> list[tuple]:
    """Compile a single path segment into tokens."""
    if segment == '**':
        return [('**',)]

    tokens = []
    i = 0
    while i < len(segment):
        if segment[i] == '*':
            tokens.append(('*',))
            i += 1
        elif segment[i] == '?':
            tokens.append(('?',))
            i += 1
        elif segment[i] == '[':
            char_class, new_i = _parse_char_class(segment, i)
            tokens.append(('class', char_class))
            i = new_i
        elif segment[i] == '\\' and i + 1 < len(segment):
            tokens.append(('literal', segment[i + 1]))
            i += 2
        elif segment[i] == '\\' and i + 1 >= len(segment):
            raise PatternError(f"Dangling escape in segment: {segment}")
        else:
            tokens.append(('literal', segment[i]))
            i += 1

    return tokens


def _match_segment(tokens: list[tuple], text: str) -> bool:
    """Check if tokens match the text segment."""
    def match_recursive(token_idx: int, text_idx: int) -> bool:
        if token_idx == len(tokens):
            return text_idx == len(text)

        token = tokens[token_idx]

        if token[0] == '*':
            # Star matches zero or more characters (greedy)
            # Try matching rest of pattern from each position
            for try_text_idx in range(text_idx, len(text) + 1):
                if match_recursive(token_idx + 1, try_text_idx):
                    return True
            return False
        elif token[0] == '?':
            # Question mark matches exactly one character
            if text_idx < len(text):
                return match_recursive(token_idx + 1, text_idx + 1)
            return False
        elif token[0] == 'class':
            # Character class
            negated, chars = token[1]
            if text_idx >= len(text):
                return False
            char = text[text_idx]
            if negated:
                match = char not in chars
            else:
                match = char in chars
            if match:
                return match_recursive(token_idx + 1, text_idx + 1)
            return False
        elif token[0] == 'literal':
            # Literal character
            if text_idx < len(text) and text[text_idx] == token[1]:
                return match_recursive(token_idx + 1, text_idx + 1)
            return False

    return match_recursive(0, 0)


def _compile_pattern(pattern_text: str) -> dict:
    """Compile a pattern string into a matchable form."""
    # Split on '/' to get segments
    segments = pattern_text.split('/')

    # Determine if pattern is anchored
    is_anchored = '/' in pattern_text
    if is_anchored and segments and segments[0] == '':
        # Leading slash - remove it and it's still anchored
        segments = segments[1:]

    # Compile each segment
    compiled_segments = []
    for segment in segments:
        compiled_segments.append(_compile_segment(segment))

    return {
        'anchored': is_anchored,
        'segments': compiled_segments,
    }


def _match_pattern(compiled: dict, path: str, is_dir: bool) -> bool:
    """Check if a path matches a compiled pattern."""
    segments = compiled['segments']
    anchored = compiled['anchored']
    path_segments = path.split('/')

    if not anchored:
        # Basename matching: try to match against each suffix of path segments
        # But really, we just need to match the basename
        basename = path_segments[-1]
        if len(segments) == 1 and segments[0] != [('**',)]:
            # Simple basename pattern
            return _match_segment(segments[0], basename)
        elif segments[0] == [('**',)]:
            # Leading ** followed by more segments
            if len(segments) == 1:
                return True  # ** alone matches everything
            # Try matching the rest of the segments starting from different positions
            return _match_path_segments(segments[1:], path_segments, is_greedy_start=True)
        else:
            # Multiple segments in a basename-only pattern doesn't make sense
            # But per spec, a basename pattern with no slash matches just the basename
            return False
    else:
        # Anchored pattern: match from the start
        return _match_path_segments(segments, path_segments, is_greedy_start=False)


def _match_path_segments(pattern_segments: list, path_segments: list, is_greedy_start: bool) -> bool:
    """Match pattern segments against path segments."""
    def match_rec(p_idx: int, path_idx: int) -> bool:
        # Base case: consumed all pattern segments
        if p_idx == len(pattern_segments):
            # All path segments must be consumed
            return path_idx == len(path_segments)

        pattern_seg = pattern_segments[p_idx]

        # Handle ** segments
        if pattern_seg == [('**',)]:
            # Handle trailing ** - matches one or more segments
            if p_idx == len(pattern_segments) - 1:
                # Trailing **: match one or more remaining path segments
                return path_idx < len(path_segments)
            else:
                # Middle **: match zero or more segments
                # Try each possibility
                for try_path_idx in range(path_idx, len(path_segments) + 1):
                    if match_rec(p_idx + 1, try_path_idx):
                        return True
                return False

        # Regular segment matching
        if path_idx >= len(path_segments):
            return False

        if _match_segment(pattern_seg, path_segments[path_idx]):
            return match_rec(p_idx + 1, path_idx + 1)
        return False

    if is_greedy_start and pattern_segments:
        # For basename patterns like *.log, match against just the basename
        # This shouldn't be reached based on the logic above
        return False

    return match_rec(0, 0)


def is_ignored(patterns: list[str], path: str, is_dir: bool) -> bool:
    """Return True when `path` is ignored by `patterns`."""
    compiled_patterns = []

    # Parse and compile all patterns first
    for line in patterns:
        parsed = _parse_pattern_line(line)
        if parsed is not None:
            is_negation, is_dir_only, pattern_text = parsed
            try:
                compiled = _compile_pattern(pattern_text)
            except PatternError:
                raise
            compiled_patterns.append((is_negation, is_dir_only, compiled))

    # Walk patterns in order, last match decides
    matched = False
    for is_negation, is_dir_only, compiled in compiled_patterns:
        # Directory-only patterns don't match non-directories
        if is_dir_only and not is_dir:
            continue

        if _match_pattern(compiled, path, is_dir):
            matched = not is_negation

    return matched
